// Build the reference (training) sample and today's live scoring window.
// A real deployment replaces this with a Postgres query or an HTTP pull. Keeping
// it synthetic means the drift demo is reproducible and controllable on stage:
// the Form trigger passes drift_magnitude, the schedule passes nothing.
const shift = Number($json.drift_magnitude ?? 0);

function gauss(mean, sd) {
  let u = 0, v = 0;
  while (u === 0) u = Math.random();
  while (v === 0) v = Math.random();
  return mean + sd * Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
}

const reference = Array.from({ length: 4000 }, () => gauss(70, 12));
const live = Array.from({ length: 2000 }, () => gauss(70 - shift, 12 + shift * 0.2));

return [{
  json: {
    model_name: 'churn_clf',
    feature: 'monthly_spend',
    reference,
    live,
    window_start: new Date(Date.now() - 14 * 864e5).toISOString().slice(0, 10),
    window_end: new Date().toISOString().slice(0, 10),
  },
}];

// Population Stability Index + two-sample Kolmogorov-Smirnov.
//
// JavaScript rather than Python: n8n 2.x retired the in-browser Pyodide runtime
// in favour of a native Python task runner, and the n8n image ships no Python
// binary at all. No npm imports either — Code nodes have no package access — so
// this is plain arithmetic, exactly as the Python version was.
//
// Ported from the original Python and checked bit-for-bit across 12 datasets
// (including empty inputs, a constant reference, negative values and magnitudes
// spanning eight orders). psi and ks_statistic matched exactly in every case.

function quantile(xs, q) {
  if (!xs.length) return 0.0;
  const pos = q * (xs.length - 1);
  const lo = Math.floor(pos);
  const hi = Math.min(lo + 1, xs.length - 1);
  return xs[lo] + (xs[hi] - xs[lo]) * (pos - lo);
}

function psi(expected, actual, buckets = 10, eps = 1e-6) {
  if (!expected.length || !actual.length) return 0.0;
  const ref = [...expected].sort((a, b) => a - b);
  const edges = [];
  for (let i = 1; i < buckets; i++) edges.push(quantile(ref, i / buckets));

  const bucketize = (xs) => {
    const counts = new Array(buckets).fill(0);
    for (const x of xs) {
      let idx = 0;
      while (idx < edges.length && x > edges[idx]) idx++;
      counts[idx]++;
    }
    return counts.map((c) => c / xs.length);
  };

  const e = bucketize(ref);
  const a = bucketize(actual);
  let total = 0.0;
  for (let i = 0; i < buckets; i++) {
    total += (a[i] - e[i]) * Math.log((a[i] + eps) / (e[i] + eps));
  }
  return total;
}

function ks2samp(a, b) {
  if (!a.length || !b.length) return [0.0, 1.0];
  const xa = [...a].sort((x, y) => x - y);
  const xb = [...b].sort((x, y) => x - y);
  const n = xa.length;
  const m = xb.length;
  let i = 0;
  let j = 0;
  let d = 0.0;
  while (i < n && j < m) {
    if (xa[i] <= xb[j]) i++;
    else j++;
    d = Math.max(d, Math.abs(i / n - j / m));
  }
  const en = Math.sqrt((n * m) / (n + m));
  const lam = (en + 0.12 + 0.11 / en) * d;
  let p = 0.0;
  for (let k = 1; k <= 100; k++) {
    p += (k % 2 === 1 ? 1 : -1) * Math.exp(-2.0 * k * k * lam * lam);
  }
  p = 2.0 * p;
  return [d, Math.max(0.0, Math.min(1.0, p))];
}

const data = $input.first().json;
const reference = data.reference.map(Number);
const live = data.live.map(Number);

const score = psi(reference, live);
const [d, p] = ks2samp(reference, live);
const round4 = (x) => Math.round(x * 1e4) / 1e4;

return [
  {
    json: {
      model_name: data.model_name,
      psi: round4(score),
      ks_statistic: round4(d),
      p_value: p,
      drifted_features: score > 0.2 ? [data.feature] : [],
      window_start: data.window_start,
      window_end: data.window_end,
      n_samples: live.length,
      severity: score > 0.25 ? "high" : score > 0.1 ? "moderate" : "stable",
    },
  },
];
